def process(self, argv, *args, **kwargs):
    result = super().process(argv, *args, **kwargs)
    values = list(map(str, argv))
    if hasattr(self, 'quality') and str(ENTRY) in values and '--state' in values:
        command = values[values.index('--state') + 2]
